<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { useFullPortal } from '../fullCoursePortal'
import { parseFull,fullAutomaticScore } from '../fullCourseDomain'
import FullSubmissionEvidence from './FullSubmissionEvidence.vue'
const portal=useFullPortal(),selectedId=ref<number|null>(null),filter=ref<'all'|'pending'|'reviewed'>('all'),file=ref<HTMLInputElement>()
const rows=computed(()=>portal.submissions.filter(r=>filter.value==='all'||(filter.value==='pending'?!r.reviews.length:!!r.reviews.length)))
watch(rows,r=>{if(!r.some(x=>x.id===selectedId.value))selectedId.value=r[0]?.id??null},{immediate:true})
const selected=computed(()=>portal.submissions.find(r=>r.id===selectedId.value)),snapshot=computed(()=>selected.value?parseFull(selected.value.snapshotJson):null)
const form=ref({reviewer:'',needs:0,architecture:0,feedback:'',recordIds:[] as number[]})
watch(selected,entry=>{const r=entry?.reviews.at(-1);form.value={reviewer:r?.reviewer??'',needs:r?.needs??0,architecture:r?.architecture??0,feedback:r?.feedback??'',recordIds:r?[...r.recordIds]:[]}},{immediate:true})
function grade(){if(selected.value)portal.grade(selected.value.id,{...form.value,recordIds:[...form.value.recordIds]})}
function download(text:string,name:string){const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importFile(event:Event){const input=event.target as HTMLInputElement,f=input.files?.[0];try{if(f){if(f.size>24_000_000)throw Error('批阅备份不能超过24 MB。');portal.importJson(await f.text())}}catch(e){portal.message=e instanceof Error?e.message:'读取失败，原列表未改变。'}input.value=''}
</script>
<template><main class="teacher-workspace full-teacher"><aside class="teacher-inbox"><div class="core-eyebrow">完整课程 · 教师端演示</div><h1>第一阶段成果批阅</h1><p>只读取已提交的冻结快照。试课实验成绩单独保存。</p><label class="field"><span>批阅筛选</span><select v-model="filter" aria-label="完整课程批阅筛选"><option value="all">全部提交</option><option value="pending">待批阅</option><option value="reviewed">已批阅</option></select></label><button v-for="r in rows" :key="r.id" class="submission-row" :class="{active:r.id===selectedId}" @click="selectedId=r.id"><b>第一阶段 · 提交V{{ r.id }}</b><small>{{ new Date(r.submittedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}) }}</small><span>{{ r.reviews.length?'已批阅':'待批阅' }}</span></button><p v-if="!rows.length">尚无相应提交。</p><button class="btn" @click="download(portal.exportJson(),'完整课程-提交与批阅.json')">导出完整课程批阅备份</button><button class="core-link" @click="file?.click()">导入批阅备份</button><button v-if="portal.originalUnreadable" class="core-link" @click="download(portal.originalUnreadable,'完整课程-批阅原始诊断.json')">导出批阅原始诊断</button><input ref="file" class="hidden" type="file" accept=".json" aria-label="完整课程批阅备份文件" @change="importFile" /></aside>
 <section class="teacher-main"><p v-if="portal.error" class="core-warning">{{ portal.error }}</p><p v-if="portal.message" class="full-feedback" role="status">{{ portal.message }}</p><template v-if="selected&&snapshot"><section class="core-card"><div class="core-eyebrow">冻结成果 · 提交V{{ selected.id }}</div><h1>对象建模与系统设计</h1><FullSubmissionEvidence :snapshot="snapshot" /></section><section class="core-card"><h2>评价需求与架构论证</h2><p>需求5分：需求完整2分、验收条件明确3分。架构5分：边界清晰2分、依赖正确2分、隔离有效1分。操作证据 {{ fullAutomaticScore(snapshot) }}/14，单独计算。</p><form @submit.prevent="grade"><label class="field"><span>复核教师</span><input v-model="form.reviewer" aria-label="完整课程复核教师" maxlength="10000" required /></label><div class="full-grid-two"><label class="field"><span>需求与验收条件 /5</span><input v-model.number="form.needs" aria-label="完整课程需求评分" type="number" min="0" max="5" step="1" required /></label><label class="field"><span>架构与隔离论证 /5</span><input v-model.number="form.architecture" aria-label="完整课程架构评分" type="number" min="0" max="5" step="1" required /></label></div><p>引用的验证记录：</p><div class="core-compare-choices"><label v-for="r in snapshot.records" :key="r.id"><input v-model="form.recordIds" type="checkbox" :value="r.id" />#{{ r.id }}（步骤{{ r.step }}）</label></div><label class="field"><span>依据与改进反馈</span><textarea v-model="form.feedback" aria-label="完整课程教师反馈" maxlength="10000" rows="4" required /></label><button class="btn primary" type="submit">保存对本版本的批阅</button></form></section><section class="core-card"><h2>本版本评价历史</h2><p v-if="!selected.reviews.length">尚未批阅。</p><p v-for="(r,i) in selected.reviews" :key="i" class="full-preserve">{{ r.reviewer }} · {{ new Date(r.at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}) }} · 需求{{ r.needs }}/5，架构{{ r.architecture }}/5<br>{{ r.feedback }}</p></section></template><section v-else class="core-card"><h2>选择一个已提交的第一阶段成果</h2><p>学生完成步骤1—7并提交后，本地列表中会生成独立快照。未提交的草稿不进入此列表。</p></section></section>
</main></template>
